describe('SUPERVISOR_LOG_ROTATION_THRESHOLD_BYTES', () => {
  test('es el umbral de la referencia (`at` = 10 MiB)', () => {
    expect(SUPERVISOR_LOG_ROTATION_THRESHOLD_BYTES).toBe(10_485_760)
  })
